package oauth

import (
	"encoding/hex"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// legacySecretHex and legacyBlobHex are a token file and its sibling secret
// generated by the pre-migration encrypted backend (internal/oauth/encrypt.go,
// since removed): ProviderKey("demo") holding access "fixture-access-123",
// refresh "fixture-refresh-456", account "me@x". The on-disk layout is
// AES-256-GCM nonce||ciphertext with a 32-byte raw secret, byte-identical to
// what internal/securefile produces, so the migrated store must read it.
const (
	legacySecretHex = "46587710bad78334bd4c14d3ab9d30995580a48ee5be73c9d7ff27ae0984f391"
	legacyBlobHex   = ""
)

// TestEncryptedStoreReadsFileWrittenByLegacyBackend proves the disk format is
// unchanged by the migration to internal/securefile: a file sealed by the old
// code decrypts under the new one.
func TestEncryptedStoreReadsFileWrittenByLegacyBackend(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "oauth-tokens.json")
	secret, err := hex.DecodeString(legacySecretHex)
	if err != nil {
		t.Fatalf("decode legacy secret: %v", err)
	}
	blob, err := hex.DecodeString(legacyBlobHex)
	if err != nil {
		t.Fatalf("decode legacy blob: %v", err)
	}
	if err := os.WriteFile(path+".secret", secret, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, blob, 0o600); err != nil {
		t.Fatal(err)
	}
	s, err := NewStore(StoreOptions{FilePath: path, Storage: "encrypted-file"})
	if err != nil {
		t.Fatalf("NewStore: %v", err)
	}
	got, ok, err := s.Load(ProviderKey("demo"))
	if err != nil || !ok {
		t.Fatalf("Load = %+v ok=%v err=%v, want the legacy login", got, ok, err)
	}
	if got.AccessToken != "fixture-access-123" || got.RefreshToken != "fixture-refresh-456" || got.Account != "me@x" {
		t.Fatalf("legacy login mismatch: %+v", got)
	}
}

// TestEncryptedStoreReclaimsOrphanSecretLock reproduces the pre-migration
// wedge: a crash between creating "<secret>.lock" and publishing the secret
// left the lock behind, and the old backend had no stale-lock reclaim, so
// every later creation timed out. The migrated backend (securefile) reclaims a
// lock older than its stale threshold and proceeds.
func TestEncryptedStoreReclaimsOrphanSecretLock(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "oauth-tokens.json")
	lockPath := path + ".secret.lock"
	if err := os.WriteFile(lockPath, []byte("orphan-from-crash"), 0o600); err != nil {
		t.Fatal(err)
	}
	stale := time.Now().Add(-time.Minute)
	if err := os.Chtimes(lockPath, stale, stale); err != nil {
		t.Fatal(err)
	}
	s, err := NewStore(StoreOptions{FilePath: path, Storage: "encrypted-file"})
	if err != nil {
		t.Fatalf("NewStore: %v", err)
	}
	if err := s.Save(ProviderKey("demo"), Token{AccessToken: "after-crash"}); err != nil {
		t.Fatalf("Save with orphaned secret lock must reclaim it, got: %v", err)
	}
	got, ok, err := s.Load(ProviderKey("demo"))
	if err != nil || !ok || got.AccessToken != "after-crash" {
		t.Fatalf("Load = %+v ok=%v err=%v", got, ok, err)
	}
}

func newEncryptedStore(t *testing.T) (*Store, string) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "oauth-tokens.json")
	s, err := NewStore(StoreOptions{FilePath: path, Encrypted: true})
	if err != nil {
		t.Fatalf("NewStore(encrypted): %v", err)
	}
	return s, path
}

// The unified Storage="encrypted-file" selector must encrypt at rest, the same as
// the legacy Encrypted:true alias (the file/keyring/encrypted-file merge).
func TestNewStoreEncryptedFileStorageSelector(t *testing.T) {
	path := filepath.Join(t.TempDir(), "oauth-tokens.json")
	s, err := NewStore(StoreOptions{FilePath: path, Storage: "encrypted-file"})
	if err != nil {
		t.Fatalf("NewStore(encrypted-file): %v", err)
	}
	if err := s.Save(ProviderKey("demo"), Token{AccessToken: "super-secret-access"}); err != nil {
		t.Fatalf("Save: %v", err)
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read: %v", err)
	}
	if strings.Contains(string(raw), "super-secret-access") || strings.Contains(string(raw), "schemaVersion") {
		t.Fatalf("Storage=encrypted-file did not encrypt at rest:\n%s", raw)
	}
	got, ok, err := s.Load(ProviderKey("demo"))
	if err != nil || !ok || got.AccessToken != "super-secret-access" {
		t.Fatalf("Load = %+v ok=%v err=%v", got, ok, err)
	}
}

func TestEncryptedStoreRoundTripAndCiphertextOnDisk(t *testing.T) {
	s, path := newEncryptedStore(t)
	tok := Token{AccessToken: "super-secret-access", RefreshToken: "super-secret-refresh", Account: "me@x"}
	if err := s.Save(ProviderKey("demo"), tok); err != nil {
		t.Fatalf("Save: %v", err)
	}
	// On-disk file must be ciphertext: not valid JSON, no plaintext token.
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read file: %v", err)
	}
	if strings.Contains(string(raw), "super-secret-access") || strings.Contains(string(raw), "schemaVersion") {
		t.Fatalf("token file is not encrypted at rest:\n%s", raw)
	}
	// The secret file exists beside it.
	if _, err := os.Stat(path + ".secret"); err != nil {
		t.Fatalf("secret file missing: %v", err)
	}
	// A fresh Store (same path) decrypts and reads it back.
	s2, err := NewStore(StoreOptions{FilePath: path, Encrypted: true})
	if err != nil {
		t.Fatalf("NewStore 2: %v", err)
	}
	got, ok, err := s2.Load(ProviderKey("demo"))
	if err != nil || !ok || got.AccessToken != "super-secret-access" || got.Account != "me@x" {
		t.Fatalf("Load = %+v ok=%v err=%v", got, ok, err)
	}
	// Delete + Status work through the encrypted backend too.
	statuses, err := s2.Status(KeyPrefixProvider)
	if err != nil || len(statuses) != 1 {
		t.Fatalf("Status = %+v err=%v", statuses, err)
	}
	if removed, err := s2.Delete(ProviderKey("demo")); err != nil || !removed {
		t.Fatalf("Delete = %v %v", removed, err)
	}
}

func TestEncryptedStoreTamperFailsClosed(t *testing.T) {
	s, path := newEncryptedStore(t)
	if err := s.Save(ProviderKey("demo"), Token{AccessToken: "a"}); err != nil {
		t.Fatalf("Save: %v", err)
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read file: %v", err)
	}
	if len(raw) == 0 {
		t.Fatal("encrypted token file is empty")
	}
	raw[len(raw)-1] ^= 0xff
	if err := os.WriteFile(path, raw, 0o600); err != nil {
		t.Fatalf("rewrite: %v", err)
	}
	if _, _, err := s.Load(ProviderKey("demo")); err == nil {
		t.Fatal("a tampered encrypted store must fail closed")
	}
}

func TestEncryptedStoreMissingSecretFailsClosed(t *testing.T) {
	s, path := newEncryptedStore(t)
	if err := s.Save(ProviderKey("demo"), Token{AccessToken: "a"}); err != nil {
		t.Fatalf("Save: %v", err)
	}
	if err := os.Remove(path + ".secret"); err != nil {
		t.Fatalf("remove secret: %v", err)
	}
	if _, _, err := s.Load(ProviderKey("demo")); err == nil {
		t.Fatal("missing secret must fail closed, not return empty")
	}
}
